import type { ReactNode } from 'react';
import './mi-light.css';
import { mpFontFaceCss } from '@/lib/public-site/fonts';
import MiLightRoot from './MiLightRoot';

const SERIF_FACES = mpFontFaceCss({ includeInter: false });

/**
 * The light "homepage + map" look for pages built in the old dark Tailwind style.
 *
 * mi-light.css (generated by scripts/gen-app-light-theme.mjs) re-colours the dark palette
 * utilities under `.mi-light`, so a dark page turns light without rewriting its classes.
 * The wrapper covers SSR; MiLightRoot also puts the class on <html> so portals match.
 * Used by /app and every legacy dark page's layout (2026-11-07). Public-site pages
 * (PublicShell, --mp-* tokens) must NOT use it: their navy buttons would lose white text.
 */
export default function LightThemeScope({ children }: { children: ReactNode }) {
  return (
    <div className="mi-light min-h-dvh">
      <style dangerouslySetInnerHTML={{ __html: SERIF_FACES }} />
      <MiLightRoot />
      {children}
    </div>
  );
}
